const outputs = [];

for (const item of $input.all()) {
  const data = item.json ?? {};
  const structuredFromNode = data.structuredData || {};
  const documentType = data.documentType || 'intakeForm';

  const formFields = data.body?.FieldsInfo?.Fields || [];
  const text = data.body?.fillText || '';

  const fieldMap = Object.fromEntries(formFields.map(f => [String(f.pageFieldName || '').trim(), f.fieldValue ?? '']));

  const sdCase = structuredFromNode.caseInfo || {};
  const clientName = sdCase.clientName || 'Unknown Client';
  const attorneyName = sdCase.attorneyName || 'Unknown Attorney';
  const caseRef = sdCase.caseReference || 'Unknown Case';

  const promptText = `Analyze the following legal document and extract key information.\nDocument Type: ${documentType}\nClient Name: ${clientName}\nAttorney Name: ${attorneyName}\nCase Reference: ${caseRef}\n\nDocument Content:\n${text}\n\nForm Fields:\n${JSON.stringify(fieldMap, null, 2)}\n\nPlease structure the output in JSON format with the following keys: 'summary', 'keyFacts', 'partiesInvolved', 'potentialIssues'.`;

  outputs.push({
    json: {
      aiPrompt: promptText,
      documentType: documentType,
      structuredData: structuredFromNode
    }
  });
}

return outputs;

// This node ensures 'documentType' and 'caseId' are preserved after the OpenAI call.
const openAIResult = $input.first().json;
const originalData = $items('Build AI Prompt')[0].json;

// Re-structure the output to carry through essential data
return [{
  json: {
    ...openAIResult,
    documentType: originalData.documentType,
    // Ensure structuredData (containing caseId) is passed through
    structuredData: originalData.structuredData
  }
}];

const item = $input.first().json;
const originalStructuredData = $items('Add DocumentType')[0].json.structuredData;
return [{ json: { parsedData: item.message.content, documentType: 'intakeForm', structuredData: originalStructuredData } }];

const item = $input.first().json;
const originalStructuredData = $items('Add DocumentType')[0].json.structuredData;
return [{ json: { parsedData: item.message.content, documentType: 'caseDocument', structuredData: originalStructuredData } }];

// Generate debug package with workflow data for UI visibility
const debugPackage = {
  timestamp: new Date().toISOString(),
  workflow: '2_ai_processing',
  inputItemCount: $input.all().length,
  nodeExecutionData: $input.all(),
  executionInfo: {
    nodeId: 'Generate & Send Debug Package',
    processingTime: new Date().toISOString(),
    dataTypes: $input.all().map(item => ({
      hasJson: !!item.json,
      hasBinary: !!item.binary,
      jsonKeys: item.json ? Object.keys(item.json) : [],
      binaryKeys: item.binary ? Object.keys(item.binary) : []
    }))
  }
};

// Return both debug output (visible in Node Output → JSON) and pass-through data
return [
  // First output: Debug data (visible in UI)
  { 
    json: { 
      debug: debugPackage,
      message: 'Debug package generated - check Node Output → JSON tab'
    } 
  },
  // Remaining outputs: Pass through original data for workflow continuation
  ...$input.all()
];
